bins = {color_1: (x_1, y_1), color_2: (x_2, y_2), color_3: (x_3, y_3)}
dets = see(list(bins))
pending = dict(dets)
while pending:
    ready = []
    for c in pending:
        bx, by = bins[c]
        blocked = False
        for oc in pending:
            o = pending[oc]
            if oc != c and math.hypot(o.position[0] - bx, o.position[1] - by) < 0.06:
                blocked = True
        if not blocked:
            ready.append(c)
    if not ready:
        ready = [list(pending)[0]]
    color = min(ready, key=lambda c: dist_xy(pending[c], bins[c]))
    d = pending.pop(color)
    pick = grasp_pose(d, dets.values())
    place = Pose(bins[color][0], bins[color][1], pick.z)
    pick_place(pick, place, APPROACH)

